using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "KarmicExchangeActionCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Orion/KarmicExchangeActionCustomDescription", order = 0)]
public class KarmicExchangeActionCustomDescription : BattleActionWithMinimumAstriumActionCustomDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		KarmicExchangeAction karmicExchangeAction = battleAction as KarmicExchangeAction;
		string firstArgument = Smart.Format(base.localizationManager.GetLocalizedCastOrbActionBase(), karmicExchangeAction.StarAbility.StarAbilityID.GetSpriteText() + karmicExchangeAction.StarAbility.GetLocalizedNameWithoutModifiers());
		firstArgument = base.localizationManager.GetLocalizedXTimesFormatted(firstArgument, karmicExchangeAction.KarmicOrbActivationAmount);
		return base.GetActionDescription(amountModified, battleAction) + "\n" + firstArgument;
	}
}
